import * as THREE from 'three/webgpu';
import { sampler } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Atlas region dimensions (512x320 from spec)
  const atlasRegion = config.atlasRegion || { x: 0, y: 0, width: 512, height: 320 };
  const aspectRatio = atlasRegion.width / atlasRegion.height;

  // Create plane geometry with correct aspect ratio
  const height = 1.0;
  const width = height * aspectRatio;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load texture from asset URL
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // Create material using TSL nodes
  const material = new THREE.MeshBasicNodeMaterial({
    colorNode: sampler(texture),
    transparent: true,
    depthWrite: false,
    side: THREE.DoubleSide,
  });

  // Create mesh
  const mesh = new THREE.Mesh(geometry, material);

  // Apply scene placement configuration
  if (config.placement) {
    mesh.position.fromArray(config.placement.position);
    mesh.rotation.order = 'XYZ';
    mesh.rotation.fromArray(config.placement.rotation);
    mesh.scale.fromArray(config.placement.scale);
  }

  group.add(mesh);

  // Resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // Event handlers (none for static sprite)
  group.userData.handlers = {};

  return group;
}
